<?php
require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../includes/session.php';require_once __DIR__.'/../../includes/functions.php';require_once __DIR__.'/../../includes/admin_layout.php';if(!is_admin_logged_in())redirect('../../index.php');if(($_SESSION['admin_role']??'admin')!=='admin'){http_response_code(403);exit('Administrator access required.');}$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){if(!verify_csrf_token($_POST['csrf_token']??''))$error='Security token expired.';else{$id=(int)($_POST['id']??0);$decision=$_POST['decision']??'';$notes=trim($_POST['notes']??'');if(in_array($decision,['verified','rejected'],true)){pg_query($conn,'BEGIN');$r=pg_query_params($conn,"UPDATE payments SET status=$1,verified_by=$2,verified_at=NOW(),verifier_notes=$3 WHERE id=$4 AND status='pending' RETURNING fine_id",[$decision,$_SESSION['admin_id'],$notes,$id]);if($r&&pg_num_rows($r)){$fineId=pg_fetch_result($r,0,'fine_id');if($fineId)pg_query_params($conn,"UPDATE fines SET status=$1 WHERE id=$2",[$decision==='verified'?'paid':'unpaid',$fineId]);pg_query($conn,'COMMIT');audit_log($conn,'payment_'.$decision,'payment',$id);redirect('index.php');}pg_query($conn,'ROLLBACK');$error='Pending payment not found.';}}}
$q=trim($_GET['q']??'');$params=[];$where='';if($q!==''){$params=['%'.$q.'%'];$where='WHERE a.full_name ILIKE $1 OR a.attendee_code ILIKE $1 OR a.course ILIKE $1 OR d.name ILIKE $1';}$sql="SELECT p.*,a.full_name,a.attendee_code,a.course,a.year_level,a.section,d.name department_name,f.description fine_description,ad.full_name verifier_name FROM payments p JOIN attendees a ON a.id=p.attendee_id LEFT JOIN departments d ON d.id=a.department_id LEFT JOIN fines f ON f.id=p.fine_id LEFT JOIN admins ad ON ad.id=p.verified_by $where ORDER BY CASE p.status WHEN 'pending' THEN 0 ELSE 1 END,p.submitted_at DESC";$rows=$params?pg_query_params($conn,$sql,$params):pg_query($conn,$sql);admin_page_start('Payment Ledger','payments');?>
<div class="hero"><div><h2><i class="fas fa-receipt"></i> Payment Ledger</h2><p>Search students, review uploaded receipts, and verify fine payments.</p></div></div><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><div class="card"><form method="get" class="actions"><input name="q" value="<?=h($q)?>" placeholder="Student, course, or department"><button class="btn">Search</button></form></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Fine / Amount</th><th>Payment</th><th>Receipt</th><th>Status</th><th>Verification</th></tr></thead><tbody><?php if($rows):while($p=pg_fetch_assoc($rows)):?><tr><td><strong><?=h($p['full_name'])?></strong><div class="help"><?=h($p['attendee_code'].' · '.$p['course'].' '.$p['year_level'].' '.$p['section'])?><br><?=h($p['department_name']?:'')?></div></td><td><?=h($p['fine_description']?:'Payment')?><div><strong>₱<?=number_format((float)$p['amount'],2)?></strong></div></td><td><?=h(ucfirst($p['payment_method']))?><div class="help"><?=h($p['receipt_number']?:'No receipt number')?></div></td><td><?=$p['receipt_path']?'<a class="btn small secondary" target="_blank" href="receipt.php?id='.(int)$p['id'].'">View receipt</a>':'—'?></td><td><span class="badge <?=h($p['status'])?>"><?=h(ucfirst($p['status']))?></span><div class="help"><?=h($p['verifier_name']?:'')?></div></td><td><?php if($p['status']==='pending'):?><form method="post" class="actions"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$p['id']?>"><input name="notes" placeholder="Remarks"><button class="btn small" name="decision" value="verified">Verify</button><button class="btn small danger" name="decision" value="rejected">Reject</button></form><?php else:?><?=h($p['verifier_notes']?:'—')?><?php endif;?></td></tr><?php endwhile;endif;?></tbody></table></div></div><?php admin_page_end();?>
